#!/bin/sh
# GENERATED by bake.py from /etc/event.d/ce-register-cryptofs-services -- do not edit.
# Lives outside the job because upstart segfaults spawning a job
# with a large inline script (see externalise_job_scripts).
# Run by that job as `sh -e`: a lone failing command aborts it.
    LOG=/var/log/ce-register-cryptofs-services.log
    log() { echo "$(date 2>/dev/null) $*" >> $LOG 2>/dev/null; }
    L2=/var/palm/ls2
    changed=""
    for N in org.webosarchive.photos.service; do
        [ -f $L2/services/pub/$N ] && [ -f $L2/services/prv/$N ] && continue
        D=/media/cryptofs/apps/usr/palm/services/$N
        # the preload pass may not have installed it yet: wait up to 15 minutes
        n=0
        while [ ! -f $D/services.json ] && [ $n -lt 90 ]; do sleep 10; n=$((n+1)); done
        if [ ! -f $D/services.json ]; then log "$N: not installed -- next boot"; continue; fi
        mkdir -p $L2/roles/pub $L2/roles/prv $L2/services/pub $L2/services/prv
        for B in pub prv; do
            printf '{\n\t"role": {\n\t\t"exeName": "js",\n\t\t"type": "regular",\n\t\t"allowedNames": ["%s"]\n\t},\n\t"permissions": [\n\t\t{\n\t\t\t"service": "%s",\n\t\t\t"outbound": ["*"],\n\t\t\t"inbound": ["*"]\n\t\t}\n\t]\n}\n' $N $N > $L2/roles/$B/$N.json
            printf '[D-BUS Service]\nName=%s\nExec=/usr/bin/run-js-service -n %s\n' $N $D > $L2/services/$B/$N
        done
        changed="$changed $N"
    done
    [ -n "$changed" ] || exit 0
    ls-control scan-services >/dev/null 2>&1
    sleep 3
    # verify on the bus, not the files: an unknown method means the hub found it
    for N in $changed; do
        for P in "" "-P"; do
            R=$(luna-send $P -n 1 palm://$N/ceprobe '{}' </dev/null 2>&1)
            case "$R" in
                *"Unknown method"*) log "$N: registered ($P)" ;;
                *) log "$N: NOT on the bus ($P): $R" ;;
            esac
        done
    done
